// Config plugin: turns on Android Auto Backup so daily notes and chat history
// survive an uninstall/reinstall on the same Google account, without us running
// any backend of our own — Android backs the files up to the user's own Google
// Drive "app data" space transparently.
//
// android/ is gitignored and regenerated by `expo prebuild` on every EAS build
// (see eas.json / .gitignore), so this can't be a one-off manual edit to
// AndroidManifest.xml — it has to be a plugin that reapplies on every build.
const { withAndroidManifest, withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

// Android 12+ (API 31+) backup scope. Chat/notes JSON lives in the app's "files"
// dir (expo-file-system's documentDirectory) — include it. Exclude sharedpref and
// database entirely: SecureStore's encrypted prefs can't be decrypted after a
// restore (the Keystore key that encrypted them is never backed up, by Android
// design), so restoring them would just leave corrupt, unreadable prefs on disk.
// There's no upside to restoring auth/session state anyway — the user just signs
// in again after a reinstall.
const DATA_EXTRACTION_RULES_XML = `<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
    <cloud-backup>
        <include domain="file" path="." />
    </cloud-backup>
    <device-transfer>
        <include domain="file" path="." />
    </device-transfer>
</data-extraction-rules>
`;

// Pre-Android-12 equivalent of the rules above (android:fullBackupContent).
const FULL_BACKUP_CONTENT_XML = `<?xml version="1.0" encoding="utf-8"?>
<full-backup-content>
    <include domain="file" path="." />
</full-backup-content>
`;

function withBackupRuleFiles(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const xmlDir = path.join(config.modRequest.platformProjectRoot, 'app/src/main/res/xml');
      fs.mkdirSync(xmlDir, { recursive: true });
      fs.writeFileSync(path.join(xmlDir, 'data_extraction_rules.xml'), DATA_EXTRACTION_RULES_XML);
      fs.writeFileSync(path.join(xmlDir, 'backup_rules.xml'), FULL_BACKUP_CONTENT_XML);
      return config;
    },
  ]);
}

function withBackupManifestFlags(config) {
  return withAndroidManifest(config, (config) => {
    const app = config.modResults.manifest.application?.[0];
    if (app) {
      app.$['android:allowBackup'] = 'true';
      app.$['android:fullBackupContent'] = '@xml/backup_rules';
      app.$['android:dataExtractionRules'] = '@xml/data_extraction_rules';
    }
    return config;
  });
}

module.exports = function withAndroidAutoBackup(config) {
  config = withBackupRuleFiles(config);
  config = withBackupManifestFlags(config);
  return config;
};
